SELECT ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound, COUNT(*) AS order_cnt, SUM(ws.ws_ext_sales_price) AS total_sales, AVG(ws.ws_net_profit) AS avg_profit, SUM(ws.ws_quantity) AS total_qty, RANK() OVER (ORDER BY SUM(ws.ws_ext_sales_price) DESC) AS sales_rank FROM web_sales ws JOIN income_band ib ON ws.ws_wholesale_cost BETWEEN ib.ib_lower_bound AND ib.ib_upper_bound WHERE ws.ws_sold_date_sk BETWEEN 2451383 AND 2452625 AND ws.ws_quantity > 0 GROUP BY ib.ib_income_band_sk, ib.ib_lower_bound, ib.ib_upper_bound HAVING SUM(ws.ws_ext_sales_price) > 1000 ORDER BY total_sales DESC LIMIT 10
